import {layers,fitsSlot,roleNames} from './garment-model.js';
import {outfitSeasons,outfitStyles} from './outfit-model.js';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let csrf='',library,editing,kind,restoreToken,previewURL;
const message=(s,target='#message')=>{$(target).textContent=s;};
async function api(route,{data,raw}={}){
  const write=data!==undefined||raw!==undefined;
  const response=await fetch('/mobile-api/'+route,{method:write?'POST':'GET',headers:write?{'Content-Type':raw?'application/gzip':'application/json','X-Yixu-CSRF':csrf}:{},body:raw||(write?JSON.stringify(data):undefined)});
  if(response.status===401&&route!=='login'){location.href='/login';throw Error('请重新登录');}
  if(!response.ok){const value=await response.json().catch(()=>({}));throw Error(value.error||'操作失败，请重试');}return response;
}
async function busy(button,job,target='#message'){button.disabled=true;try{await job();}catch(e){message(e.message,target);}finally{button.disabled=false;}}
if(document.body.dataset.page==='login'){
  $('#login-form').addEventListener('submit',e=>{e.preventDefault();busy(e.submitter,async()=>{await api('login',{data:{password:new FormData(e.target).get('password')}});location.href='/manage';});});
}else{
  async function load(){library=await (await api('library')).json();$('#counts').textContent=`${library.catalog.items.length} 件衣物 · ${library.state.data.outfits.length} 套搭配`;renderItems();renderOutfits();}
  const version=r=>library.versions[r.id];
  function renderItems(){const term=$('#search').value.trim().toLowerCase();const items=library.catalog.items.filter(i=>(i.name+' '+i.code).toLowerCase().includes(term));$('#item-list').innerHTML=items.length?items.map(i=>`<article class="card"><img src="/${esc(i.assets.cutout)}" alt="${esc(i.name)}" loading="lazy"><div class="card-body"><span class="code">${esc(i.code)}</span><h3>${esc(i.name)}</h3><div class="meta">${esc(i.color.name)} · ${i.wardrobeStatus==='pending-discard'?'准备丢弃':'在用'}</div><div class="actions"><button data-edit="${esc(i.id)}">编辑</button><button data-status="${esc(i.id)}">${i.wardrobeStatus==='pending-discard'?'恢复在用':'暂放一边'}</button></div></div></article>`).join(''):`<p class="empty">${term?'没有找到对应衣物。':'衣橱还是空的。<br>从一张照片开始，添加第一件衣物。'}</p>`;}
  function renderOutfits(){const outfits=library.state.data.outfits;$('#outfit-list').innerHTML=outfits.length?outfits.map(o=>`<article class="card">${o.visual?`<img src="/${esc(o.visual.src)}" alt="${esc(o.title)}" loading="lazy">`:'<div class="placeholder">衣物组合 · 暂无配图</div>'}<div class="card-body"><span class="code">${esc(o.code)}</span><h3>${esc(o.title)}</h3><div class="actions">${o.outfitKind==='planned'?'':`<button data-outfit="${esc(o.id)}">编辑</button>`}<button data-remove="${esc(o.id)}">移除搭配</button></div></div></article>`).join(''):'<p class="empty">先添加衣物，再保存喜欢的组合。<br>可上传搭配照片，也可先保存衣物清单。</p>';}
  function option(value,label,selected){return `<option value="${esc(value)}"${selected?' selected':''}>${esc(label)}</option>`;}
  const input=(name,label,value='',type='text')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" maxlength="120" required></label>`;
  function openEditor(type,record){kind=type;editing=record;$('#editor-message').textContent='';$('#editor-title').textContent=(record?'编辑':'添加')+(type==='item'?'衣物':'搭配');
    if(type==='item'){
      $('#editor-fields').innerHTML=`${record?'':`<label>衣物照片（JPEG、PNG、WebP，最大 10 MB）<input name="photo" id="photo-file" type="file" accept="image/jpeg,image/png,image/webp" required></label><img id="photo-preview" class="preview-image" alt="所选照片预览" hidden><p class="footnote">保留原照片，仅调整展示尺寸与方向，不会自动抠图。iPhone 若选到 HEIC，请先导出 JPEG。</p>`}${input('name','衣物名称',record?.name)}<div class="row"><label>类别<select name="layer">${layers.map(l=>option(l.id,l.name,l.id===(record?.layer||'inner'))).join('')}</select></label>${input('subtype','具体类型（如短袖T恤）',record?.subtype)}</div><div class="row">${input('colorName','颜色名称',record?.color?.name)}${input('hex','代表色',record?.color?.hex||'#798168','color')}</div><label>色系<select name="family">${Object.entries({unknown:'待确认',white:'白',black:'黑',gray:'灰',brown:'棕',blue:'蓝',green:'绿',red:'红',orange:'橙',yellow:'黄',purple:'紫'}).map(([id,name])=>option(id,name,id===(record?.color.family||'unknown'))).join('')}</select></label><label>适用季节（可多选）</label>${[['spring','春'],['summer','夏'],['autumn','秋'],['winter','冬']].map(([id,name])=>`<label class="check"><input type="checkbox" name="seasons" value="${id}"${record?.seasons?.includes(id)?' checked':''}>${name}</label>`).join('')}${record?'':'<label class="check"><input name="approved" type="checkbox" required>我确认照片和资料对应我实际拥有的这件衣物。</label>'}`;
    }else{
      const available=library.catalog.items.filter(i=>i.wardrobeStatus!=='pending-discard');
      $('#editor-fields').innerHTML=`${input('title','搭配名称',record?.title)}<label>季节<select name="season">${outfitSeasons.map(s=>option(s.id,s.name,s.id===(record?.season||'transition'))).join('')}</select></label><label>风格<select name="style">${outfitStyles.map(s=>option(s.id,s.name,s.id===(record?.styleTags?.[0]||'relaxed'))).join('')}</select></label>${Object.entries(roleNames).filter(([slot])=>slot!=='tie').map(([slot,name])=>`<label>${name}<select name="slot-${slot}">${option('','不选择',!record?.selection?.[slot])}${available.filter(i=>fitsSlot(i,slot)).map(i=>option(i.id,`${i.code} ${i.name}`,record?.selection?.[slot]===i.id)).join('')}</select></label>`).join('')}<label>搭配照片（选填，最大 10 MB）<input name="photo" id="photo-file" type="file" accept="image/jpeg,image/png,image/webp"></label><img id="photo-preview" class="preview-image" alt="搭配照片预览" hidden><p class="footnote">只选实际拥有的衣物。换掉已有搭配图中的衣物时，请同时上传对应的新照片。</p>`;
    }
    $('#editor').showModal();
    $('#photo-file')?.addEventListener('change',e=>{if(previewURL)URL.revokeObjectURL(previewURL);const f=e.target.files[0];if(f){previewURL=URL.createObjectURL(f);$('#photo-preview').src=previewURL;$('#photo-preview').hidden=false;}});
  }
  const readPhoto=file=>new Promise((resolve,reject)=>{if(file.size>10*1024*1024)return reject(Error('照片不能超过 10 MB'));const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('照片读取失败'));reader.readAsDataURL(file);});
  $('#edit-form').addEventListener('submit',e=>{e.preventDefault();const submittedKind=kind,submittedEditing=editing;busy(e.submitter,async()=>{const form=new FormData(e.target),p={};if(submittedEditing){p.id=submittedEditing.id;p.expected=version(submittedEditing);}const photo=form.get('photo');if(photo?.size)p.photo=await readPhoto(photo);
    if(submittedKind==='item'){for(const k of ['name','layer','subtype','colorName','hex','family'])p[k]=form.get(k);p.seasons=form.getAll('seasons');p.approved=form.get('approved')==='on';}else{p.title=form.get('title');p.season=form.get('season');p.styleTags=[form.get('style')];p.selection=Object.fromEntries([...form.entries()].filter(([k,v])=>k.startsWith('slot-')&&v).map(([k,v])=>[k.slice(5),v]));}
    const result=await (await api(submittedKind==='item'?'garment':'outfit',{data:p})).json();$('#editor').close();await load();message(result.message||'已保存到衣橱。');},'#editor-message');});
  $('#close-editor').onclick=()=>$('#editor').close();$('#editor').addEventListener('close',()=>{if(previewURL){URL.revokeObjectURL(previewURL);previewURL=null;}});
  $('#add-item').onclick=()=>openEditor('item');$('#add-outfit').onclick=()=>openEditor('outfit');$('#search').oninput=renderItems;
  $('#item-list').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const i=library.catalog.items.find(i=>i.id===(b.dataset.edit||b.dataset.status));if(b.dataset.edit)openEditor('item',i);else{const status=i.wardrobeStatus==='pending-discard'?'active':'pending-discard';if(!confirm(`${status==='active'?'恢复在用':'暂放到准备丢弃'}：${i.code} ${i.name}？这会保留衣物和历史记录。`))return;busy(b,async()=>{await api('status',{data:{id:i.id,expected:version(i),status}});await load();message('衣物状态已更新。');});}});
  $('#outfit-list').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const o=library.state.data.outfits.find(o=>o.id===(b.dataset.outfit||b.dataset.remove));if(b.dataset.outfit)openEditor('outfit',o);else if(confirm(`移除搭配「${o.code} ${o.title}」？衣物和原有编号会保留。`))busy(b,async()=>{await api('remove-outfit',{data:{id:o.id,expected:version(o)}});await load();message('搭配已移除。');});});
  document.querySelector('nav').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;for(const t of ['items','outfits','backup']){$('#'+t).hidden=t!==b.dataset.tab;$(`[data-tab="${t}"]`).setAttribute('aria-pressed',String(t===b.dataset.tab));}message('');});
  $('#download-backup').onclick=e=>busy(e.currentTarget,async()=>{const response=await api('backup',{data:{}}),blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`yixu-${new Date().toISOString().slice(0,10)}.yixu.gz`;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);message('备份已生成，请在 Safari 下载列表或「文件」App 中确认保存。');});
  $('#restore-file').onchange=()=>{restoreToken=null;$('#restore-preview').hidden=true;};
  $('#preview-restore').onclick=e=>busy(e.currentTarget,async()=>{const file=$('#restore-file').files[0];if(!file)throw Error('请先选择衣序备份文件');if(file.size>300*1024*1024)throw Error('备份文件超过上传限制');const r=await(await api('restore-preview',{raw:file})).json();restoreToken=r.token;$('#restore-summary').textContent=`校验通过：${r.garments} 件衣物、${r.outfits} 套搭配。确认恢复会切换为这份备份中的内容；当前数据会另行保留。`;$('#restore-confirm').value='';$('#restore-preview').hidden=false;message('请核对数量，再确认恢复。');});
  $('#apply-restore').onclick=e=>busy(e.currentTarget,async()=>{if(!restoreToken)throw Error('请重新上传备份进行校验');await api('restore-apply',{data:{token:restoreToken,confirm:$('#restore-confirm').value}});restoreToken=null;$('#restore-preview').hidden=true;await load();message('恢复完成，切换前的完整备份和旧数据均已保留。');});
  $('#logout').onclick=e=>busy(e.currentTarget,async()=>{await api('logout',{data:{}});location.href='/login';});
  try{csrf=(await(await api('session')).json()).csrf;await load();}catch(e){message(e.message);}
}
